import Oidc from 'oidc-client';
import { useloggedUserInfo } from "../stores/UserInfo";
const envType = process.env.VUE_APP_NODE_ENV;
class authService  { 
     mgr = null;
constructor(){
    if (envType=='development')
        {
            this.mgr = new Oidc.UserManager({
                //authority: 'https://devlogin.talygen.devlabs.com',
                //authority: 'https://stagelogin.talygen.com',
                "IdentityUrl": "https://usiclogin.talygen.com",
                client_id: 'talygenspa',
                redirect_uri:'http://localhost:9000/Content/Callback.html',
                response_type: 'id_token token',
                scope: 'openid profile',
                post_logout_redirect_uri: 'http://localhost:9000',
                userStore: new Oidc.WebStorageStateStore({ store: window.localStorage }),
                automaticSilentRenew: true,
                silent_redirect_uri: 'http://localhost:9000/Content/silent-renew.html',
                accessTokenExpiringNotificationTime: 10
            });
        }
        else if (envType=='stage'){
                this.mgr = new Oidc.UserManager({
                    authority: 'https://stagelogin.talygen.com',
                    client_id: 'talygenspa',
                    redirect_uri:'https://stage.talygen.com/Content/Callback.html',
                    response_type: 'id_token token',
                    scope: 'openid profile',
                    post_logout_redirect_uri: 'https://stage.talygen.com',
                    userStore: new Oidc.WebStorageStateStore({ store: window.localStorage }),
                    automaticSilentRenew: true,
                    silent_redirect_uri: 'https://stage.talygen.com/Content/silent-renew.html',
                    accessTokenExpiringNotificationTime: 10
            });    
        }
        else if (envType=='qa'){
            this.mgr = new Oidc.UserManager({
                authority: 'https://qatestlogin.talygen.com',
                client_id: 'talygenspa',
                redirect_uri:'https://qatestnewui.talygen.com/Content/Callback.html',
                response_type: 'id_token token',
                scope: 'openid profile',
                post_logout_redirect_uri: 'https://qatestnewui.talygen.com',
                userStore: new Oidc.WebStorageStateStore({ store: window.localStorage }),
                automaticSilentRenew: true,
                silent_redirect_uri: 'https://qatestnewui.talygen.com/Content/silent-renew.html',
                accessTokenExpiringNotificationTime: 10
            });
        }
        else if (envType=='usictest'){
            this.mgr = new Oidc.UserManager({
                authority: 'https://usictestlogin.talygen.com',
                client_id: 'talygenspa',
                redirect_uri:'https://usictest.talygen.com/Content/Callback.html',
                response_type: 'id_token token',
                scope: 'openid profile',
                post_logout_redirect_uri: 'https://usictest.talygen.com',
                userStore: new Oidc.WebStorageStateStore({ store: window.localStorage }),
                automaticSilentRenew: true,
                silent_redirect_uri: 'https://usictest.talygen.com/Content/silent-renew.html',
                accessTokenExpiringNotificationTime: 10
            });
        }
        else if (envType=="vdesklive") {
            this.mgr = new Oidc.UserManager({
                authority: 'https://applogin.vdeskworks.com',
                client_id: 'talygenspa',
                redirect_uri:'https://app.vdeskworks.com/Content/Callback.html',
                response_type: 'id_token token',
                scope: 'openid profile',
                post_logout_redirect_uri: 'https://app.vdeskworks.com',
                userStore: new Oidc.WebStorageStateStore({ store: window.localStorage }),
                automaticSilentRenew: true,
                silent_redirect_uri: 'https://app.vdeskworks.com/Content/silent-renew.html',
                accessTokenExpiringNotificationTime: 10
            });
        }
        else{
            this.mgr = new Oidc.UserManager({
                authority: 'https://applogin.talygen.com',
                client_id: 'talygenspa',
                redirect_uri:'https://app.talygen.com/Content/Callback.html',
                response_type: 'id_token token',
                scope: 'openid profile',
                post_logout_redirect_uri: 'https://app.talygen.com',
                userStore: new Oidc.WebStorageStateStore({ store: window.localStorage }),
                automaticSilentRenew: true,
                silent_redirect_uri: 'https://app.talygen.com/Content/silent-renew.html',
                accessTokenExpiringNotificationTime: 10
            });
        }
}
    signIn (returnToUrl) {
        returnToUrl ? this.mgr.signinRedirect({ state: returnToUrl })
            : this.mgr.signinRedirect();
    }
    async authenticate(returnPath) {
        const user = await this.getUser(); //see if the user details are in local storage
        if (!!user) {
            await useloggedUserInfo().setUser(user);
        } else {
            await this.signIn(returnPath);
        }
    }
    async updateUserProfileClaims(updates) {
        try {
            const user = await this.getUser();
            if (!user) {
                throw new Error('No user found to update');
            }

            // Update the profile claims
            Object.keys(updates).forEach(key => {
                user.profile[key] = updates[key];
            });

            // Get the storage key
            const authority = this.mgr.settings.authority.replace(/\/+$/, '').toLowerCase();
            const clientId = this.mgr.settings.client_id;
            const storageKey = `oidc.user:${authority}:${clientId}`;

            // Update localStorage
            localStorage.setItem(storageKey, JSON.stringify(user));

            // Update the Pinia store
            await useloggedUserInfo().setUser(user);

            console.log('User profile claims updated locally:', updates);
            return user;
        } catch (error) {
            console.error('Failed to update user profile claims:', error);
            throw error;
        }
    }
    async logOut() {   
        debugger     
        try {
            // Use signoutRedirect with method POST to avoid URL length issues
            const user = await this.mgr.getUser();
            if (user && user.id_token) {
                const signoutRequest = await this.mgr.createSignoutRequest();

                // Extract base URL and query parameters
                const url = new URL(signoutRequest.url);
                const baseUrl = url.origin + url.pathname;
                const params = new URLSearchParams(url.search);
    
                // Remove id_token_hint from the URL parameters
                params.delete('id_token_hint');
    
                // Rebuild the URL without id_token_hint
                const cleanUrl = `${baseUrl}?${params.toString()}`;
    
                // Create a form to POST the id_token_hint separately
                let form = document.createElement('form');
                form.method = 'POST';
                form.action = cleanUrl;
    
                // Add id_token_hint as hidden input
                let input = document.createElement('input');
                input.type = 'hidden';
                input.name = 'id_token_hint';
                input.value = user.id_token;
                form.appendChild(input);


                if(signoutRequest.state){
                // Add parameters as hidden inputs
                for (const [key, value] of Object.entries(signoutRequest.state.data)) {
                    let input = document.createElement('input');
                    input.type = 'hidden';
                    input.name = key;
                    input.value = value;
                    form.appendChild(input);
                }
            }
            document.body.appendChild(form);
            this.mgr.clearStaleState();
            // store.commit('set_user', null);
            //await useloggedUserInfo().setUser(null);
            const authority = this.mgr.settings.authority.replace(/\/+$/, '').toLowerCase();
            const clientId = this.mgr.settings.client_id;
            const storageKey = `oidc.user:${authority}:${clientId}`;

            // Clear OIDC user details from local storage
            localStorage.removeItem(storageKey);
            
            // user.commit('set_user', null); //clear user details in vuex
            form.submit();
            
        }
        else{
            console.log('user not found');
            alert('Error to logout. Please refresh the screen and try again ');
        }
        } catch (error) {
            console.log(error);
        }
    }
    async getUser() {
        try {
            return await this.mgr.getUser();
        } catch (err) {
            console.log(err);
        }
    }
    async refreshUser() {
        try {
            // Attempt silent signin to refresh the token
            const user = await this.mgr.signinSilent();
            
            if (user) {
                console.log('User token refreshed successfully');
                // Update the store with the new user data
                await useloggedUserInfo().setUser(user);
                return { user: user, refreshed: true };
            }
        } catch (error) {
            console.error('Failed to refresh user token silently:', error);
            
            // Check if the current user is still valid
            const currentUser = await this.getUser();
            if (currentUser && !currentUser.expired) {
                console.warn('Silent refresh failed but token still valid - token claims may be stale');
                // Return indicator that token was NOT refreshed
                // This allows caller to handle stale claims
                return { user: currentUser, refreshed: false };
            }
            
            // If we get here, the token is truly expired
            throw new Error('Token refresh failed and current token is expired');
        }
    }
}
export default new authService();