<script>
    import { storeToRefs } from "pinia";  
    import { useloggedUserInfo,moduleStore} from "./stores/UserInfo";
    const currentPath = window.location.pathname;
export default {
  data(){
    return{
       showAddWizard:false,
       showAddBookMark:false,
       showNofication:false,
       wizardType:'',
       controllerName:null,
       actionName:null,
       isShowMenuHeader:true,
       vueCurrentPath: currentPath
    }
  },
    setup() {
        const store = useloggedUserInfo();
        const modulestore = moduleStore();
        const { GetUserInfo } = storeToRefs(store);
        const { GetModuleId } = storeToRefs(modulestore);
        return { GetUserInfo, GetModuleId };
    },
}
</script>
<template>
  <section>
    <ModuleHeader v-if="(vueCurrentPath.toLowerCase() !='/company/initialsetup' && vueCurrentPath.toLowerCase() != '/client/activateclient' && GetUserInfo != null && isShowMenuHeader)" :modulemasterid="String(GetModuleId)"></ModuleHeader>   
    <section id="main-content" class="main-content" v-if="GetUserInfo != null">
      <div class="container-fluid">
          <!-- <div class="row" style="min-height:100vh;">
              <div class="col-12 mt-0 p-0"> -->
                <router-view/>
              <!-- </div>
          </div> -->
      </div>
      <tooltip :width="250"/>
    </section>
  </section> 
</template>
